    top: 45% !important;
    left: 50% !important;
    transform: translate(-50%, -50%) !important;
    color: var(--text) !important;
    font-size: 12px !important;
    font-weight: 700 !important;
    font-family: "Noto Sans CJK" !important;
    letter-spacing: 1px !important;
    white-space: nowrap !important;
    pointer-events: none !important;
    z-index: 10 !important;
    will-change: transform, opacity !important;
    transition: none !important;
    animation: text-click-reaction 2.5s ease-in-out infinite !important;
}
@keyframes text-click-reaction {
    0%   { opacity: 1; transform: translate(-50%, -50%) scale(1); }
    45%  { opacity: 1; transform: translate(-50%, -50%) scale(1); }
    50%  { opacity: 0.5; transform: translate(-50%, -50%) scale(0.95); }
    55%  { opacity: 1; transform: translate(-50%, -50%) scale(1); }
    100% { opacity: 1; transform: translate(-50%, -50%) scale(1); }
}

#load-spinner {
    --spinner-size: 12px; 
    position: absolute !important;
    top: 50% !important;
    left: 50% !important;
    margin: 0 !important; 
    width: var(--spinner-size) !important;
    height: var(--spinner-size) !important;
    background: url("https://iili.io/Cy3qWwg.png") center / contain no-repeat !important;
    transform-origin: top left !important;
    z-index: 11 !important;
    will-change: transform, opacity !important;
    transition: none !important;
    animation: mouse-click-action 2.5s ease-in-out infinite !important;
}
@keyframes mouse-click-action {
    0% {
        transform: translate(calc(-50% + 70px), calc(-50% + 40px)) rotate(0deg);
        opacity: 0;
    }
    15% { opacity: 1; }
    35%, 45% {
        transform: translate(calc(-50% + 45px), calc(-50% + 5px)) rotate(-15deg) scale(1);
    }
    50% {
        transform: translate(calc(-50% + 45px), calc(-50% + 5px)) rotate(-15deg) scale(0.75);
    }
    55%, 70% {
        transform: translate(calc(-50% + 45px), calc(-50% + 5px)) rotate(-15deg) scale(1);
    }
    85% { opacity: 0; }
    100% {
        transform: translate(calc(-50% + 70px), calc(-50% + 40px)) rotate(0deg);
        opacity: 0;
    }
